package com.yuegang.zhihui.search.infrastructure;import java.util.*;import org.springframework.web.client.RestClient;public final class DoubaoEmbeddingGateway{private final RestClient client;private final String model;public DoubaoEmbeddingGateway(String base,String key,String model){client=RestClient.builder().baseUrl(base).defaultHeader("Authorization","Bearer "+key).build();this.model=model;}public List<Double>embed(String text){Map<?,?>r=client.post().uri("/embeddings").body(Map.of("model",model,"input",List.of(text))).retrieve().body(Map.class);var data=(List<?>)Objects.requireNonNull(r).get("data");var first=(Map<?,?>)data.getFirst();return ((List<?>)first.get("embedding")).stream().map(x->((Number)x).doubleValue()).toList();}}
